local GiveScene = class("GiveScene")
local s

function GiveScene:showScene(type)
    self:removeScene()
    s = cc.CSLoader:createNode(GiveSceneCsb_filePath)
    self.give_panel = s:getChildByName("give_panel")
    s:setName("giveScene"):setScale(1280/1920)
    self.give_panel:setScale(1.333)
    SCENENOW["scene"]:addChild(s)
    local action = cc.CSLoader:createTimeline(GiveSceneCsb_filePath)
    action:retain()
    s:runAction(action)
    action:gotoFrameAndPlay(0.25, false)

    local btn_query = self.give_panel:getChildByName("btn_query")
    local my_text = self.give_panel:getChildByName("my_text")
    my_text:setString(USER_INFO["kefuId"] or "")
    local btn_close = self.give_panel:getChildByName("btn_close")
    local function  touchEvent(sender,event)
        if event == TOUCH_EVENT_BEGAN then
            sender:setScale(0.8)
        end
        --触摸取消
        if event == TOUCH_EVENT_CANCELED then
            sender:setScale(1.0)
        end

        --触摸结束
        if event == TOUCH_EVENT_ENDED then
            sender:setScale(1.0)



            if sender == btn_query then

                local tbl = {}
                local other_text =  self.give_panel:getChildByName("other_bg"):getChildByName("other_text")
                local gold_text = self.give_panel:getChildByName("gold_bg"):getChildByName("gold_text")
                local remark = self.give_panel:getChildByName("remarks_bg"):getChildByName("remarks_text")
                tbl["playerId1"] = USER_INFO["uid"]
                tbl["playerId2"] = other_text:getString()
                local gold = tonumber(gold_text:getString())
                if gold then
                    if appName == "真赢棋牌" then
                        tbl["count"] = gold * 100
                    else
                        tbl["count"] = gold
                    end

                else
                    require(CommonTips_filePath):showTips("提示", "", 3, "必须是整数")
                    return
                end
                tbl["remark"] = remark:getString()
                if type ==1 then
                    local aaa= USER_INFO["uid"].."&"..tbl["playerId2"].."*"..tbl["count"].."-yigelajidemima"
                    print(aaa,"fileMd5Code")
                    local fileMd5Code = crypto.md5(aaa,false)
                    dump(fileMd5Code,"fileMd5Code2222")
                    tbl["sign"] = fileMd5Code

                    self:reqHttp(tbl)
                elseif type == 2 then
                    SanGongSendHandle:CLIENT_CMD_GIVE_COINS(tbl["playerId2"], tbl["count"])
                end

            elseif sender == btn_close then
                self:removeScene()
            end
        end
    end
    btn_query:addTouchEventListener(touchEvent)
    btn_close:addTouchEventListener(touchEvent)
end
function GiveScene:reqHttp(tbl)
    cct.createHttRq({

        url=HttpAddr .. "/playerXXX",--http://120.76.133.49:80/hbiInterface/goods/queryGoodsList
        date=tbl,
        type_="POST",
        callBack = function ( data )

            local netData = data.netData
            netData = json.decode(netData)
            dump(netData,"playerXXX")
            if netData.returnCode == "0" then
                self:removeScene()
                require(GameScene_filePath):queryRoomCardCount()
                require(CommonTips_filePath):showTips("提示", "", 3, "赠送成功")
            else
                require(CommonTips_filePath):showTips("提示", "", 3, netData.error)
            end
        end
    })
end
function GiveScene:removeScene()

    local s = SCENENOW["scene"]:getChildByName("giveScene")
    if s then
        s:removeSelf()
    end

end
return GiveScene